event.script:
var maxFieldLength = 10;

if((xfa.event.change != 1) && (xfa.event.change != 2) && (xfa.event.change != "3") && (xfa.event.change != "4") && (xfa.event.change != "5")  && 
   (xfa.event.change != "6") && (xfa.event.change != "7") && (xfa.event.change != "8") && (xfa.event.change != "9") && (xfa.event.change != "0")){
   	// key entered is not 0-9, ignore value of the key pressed
   	console.println("Invalid key pressed - " + xfa.event.change);
	xfa.event.change = ""; 
} else {
	// key is valid 0-9, need to limit the input to maxFieldLength
	// xfa.event.selEnd will return the current position of the cusror while in the field, 0 based, so add 1 to this value or minus 1 from max field length
	if((xfa.event.selEnd + 1) >  maxFieldLength){  // test to see if the number entered > max field len,the ignore value of the key pressed
		console.println("Too many numbers entered: Field allows " + maxFieldLength + " numbers, " + (xfa.event.selEnd + 1) + " numbers entered so far, ignoring last number entered.");

		xfa.host.setFocus("form1.Page1.S1RankList");
		xfa.event.change = ""; 
	} else {
		// numbers entered is under the max field length for this field
		// xfa.event.prevText displays the contents of the field before the keystoke is added
		// xfa.event.newText displays the contents of the field after the keystoke is added (not asskgin
		console.println("VALUE=" + xfa.event.prevText + "/" + xfa.event.newText + "   LEN=" + (xfa.event.selEnd + 1));
	}	
}

