  function checkValidDateField(oDateField){
 try{
 	  var strDate = oDateField.rawValue;
		console.println("Date to check = " + oDateField.rawValue);
	var oDate = util.scand("yyyymmdd", strDate);
	console.println("check complete date change is " + oDate);
	if(oDate.isNull){
		return 0;
	} else {
		console.println("not null, return 1");
		return 1;
	} //if(oDate.isNull){			
} catch (e){
	console.println("checkValidDateField error: " + e.message);
       return 0;
	}
} 

// DATE DATE/TIME FIELD OBJECT --------------------
function checkDateRangeObjects(oDateStart, oDateEnd){
	try{
		//console.show;
		var strEnd = oDateEnd.rawValue;
		var strStart = oDateStart.rawValue;

		console.println("ending date = " + oDateEnd.rawValue);
		var endDate = util.scand("yyyymmdd", strEnd);
		var startDate = util.scand("yyyymmdd", strStart);
		console.println("Ending Date Converted = " + endDate );
		console.println("Starting Date Converted = " + startDate );
		console.println("starting diff...");
		var diff = endDate.getTime() - startDate.getTime();
		console.println("diff = " + diff);
		if(diff >= 0){
			console.println("checkDateRangeObjects --> GOOD DATE RANGE");
			rc = 1;	
		} else {
			console.println("checkDateRangeObjects --> BAD DATE RANGE");
			rc = 0;
		}
		return rc;
	} catch(e){
		console.println("checkDateRangeObjects --> error: " + e.message);
		return -1;
	} // end of try-catch
} // end of function checkDateRangeObjects(oDateStart, oDateEnd){
